import React from 'react';

const TestUpload = () => {
  return (
    <div style={{ 
      minHeight: '100vh', 
      background: 'linear-gradient(135deg, #667eea 0%, #764ba2 100%)',
      display: 'flex',
      alignItems: 'center',
      justifyContent: 'center',
      color: 'white',
      fontSize: '24px',
      fontWeight: 'bold'
    }}>
      <div style={{ textAlign: 'center' }}>
        <h1>🚀 AI Credit Decisioning Engine</h1>
        <p>Enhanced System is Working!</p>
        <p>Individual Research Insights: N Files → N Research Sections</p>
        <p>Impressive CSS Styling: ✅ Glass Morphism Design</p>
      </div>
    </div>
  );
};

export default TestUpload;
